-- =====================================================================
-- Idempotent Problem Solving submissions
-- =====================================================================
-- A submission is uniquely identified by:
--   (student_id, question_id, client_submission_id)
--
-- `client_submission_id` is generated by the browser once per logical submit.
-- Retrying the same key returns the stored submission without inserting a new
-- row or incrementing topic/session counters. Reusing a key for different code
-- or language is rejected by the backend and the RPC. Different keys remain distinct submissions even
-- when the code is identical, and the same key may be reused by another student
-- because ownership is part of the unique key.
--
-- The RPC below performs the submission insert, topic progress update and
-- session counters in one PostgreSQL transaction. It locks the student's session
-- row first, so concurrent submissions for one active session serialize and
-- counters cannot be lost to read-modify-write races.
--
-- Safety: additive only. Existing submissions are backfilled with a random key.
-- Do not apply to a live database without explicit authorization.
-- =====================================================================

alter table public.problem_submissions
  add column if not exists client_submission_id uuid,
  add column if not exists result_details jsonb not null default '[]'::jsonb,
  add column if not exists all_passed boolean not null default false,
  add column if not exists adaptive_difficulty text,
  add column if not exists adaptive_focus text,
  add column if not exists adaptive_reason text not null default '';

update public.problem_submissions
set client_submission_id = gen_random_uuid()
where client_submission_id is null;

alter table public.problem_submissions
  alter column client_submission_id set not null;

alter table public.problem_submissions
  drop constraint if exists problem_submissions_adaptive_difficulty_check;
alter table public.problem_submissions
  add constraint problem_submissions_adaptive_difficulty_check
  check (
    adaptive_difficulty is null
    or adaptive_difficulty in ('easy', 'medium', 'hard')
  );

create unique index if not exists problem_submissions_client_key_uidx
  on public.problem_submissions (student_id, question_id, client_submission_id);

comment on column public.problem_submissions.client_submission_id is
  'Client-generated idempotency key for one logical submission. Unique per student and question.';
comment on column public.problem_submissions.result_details is
  'Safe per-test response details returned to the owner after grading. Hidden inputs and expected outputs are omitted.';
comment on column public.problem_submissions.all_passed is
  'Server-computed result, stored so an idempotent retry can return the original outcome.';
comment on column public.problem_submissions.adaptive_difficulty is
  'Adaptive difficulty chosen for this submission.';
comment on column public.problem_submissions.adaptive_focus is
  'Adaptive focus chosen for this submission.';
comment on column public.problem_submissions.adaptive_reason is
  'User-facing adaptive reason chosen for this submission.';

create or replace function public.record_problem_submission(
  p_student_id uuid,
  p_question_id uuid,
  p_client_submission_id uuid,
  p_language text,
  p_code text,
  p_verdict text,
  p_passed_tests integer,
  p_total_tests integer,
  p_test_summary jsonb,
  p_result_details jsonb,
  p_all_passed boolean,
  p_hints_used integer,
  p_outcome text,
  p_next_difficulty text,
  p_next_focus text,
  p_next_topic text,
  p_next_reason text
)
returns jsonb
language plpgsql
security invoker
set search_path = public, pg_temp
as $function$
declare
  v_question public.problem_questions%rowtype;
  v_session public.problem_sessions%rowtype;
  v_session_after public.problem_sessions%rowtype;
  v_submission public.problem_submissions%rowtype;
  v_progress public.problem_topic_progress%rowtype;
  v_created boolean := false;
  v_attempts_before integer := 0;
  v_accepted_before integer := 0;
  v_hints_used integer := greatest(coalesce(p_hints_used, 0), 0);
  v_topic text;
begin
  if p_student_id is null
     or p_question_id is null
     or p_client_submission_id is null then
    raise exception 'invalid_submission_identity' using errcode = '22023';
  end if;

  -- Serialize all submissions for this student's active session. This lock is
  -- held until the function's transaction commits.
  select s.*
  into v_session
  from public.problem_sessions s
  join public.problem_questions q on q.session_id = s.id
  where q.id = p_question_id
    and q.student_id = p_student_id
    and s.student_id = p_student_id
  for update of s;

  if v_session.id is null then
    raise exception 'question_not_found' using errcode = 'P0002';
  end if;

  select q.*
  into v_question
  from public.problem_questions q
  where q.id = p_question_id
    and q.student_id = p_student_id
  for update;

  if v_question.id is null then
    raise exception 'question_not_found' using errcode = 'P0002';
  end if;

  v_topic := v_question.topic;

  -- A retry may arrive after a session was completed; return the original
  -- submission instead of creating a new attempt.
  select sub.*
  into v_submission
  from public.problem_submissions sub
  where sub.student_id = p_student_id
    and sub.question_id = p_question_id
    and sub.client_submission_id = p_client_submission_id;

  if v_submission.id is not null then
    -- The RPC validates the payload too, so a service-role caller cannot turn a
    -- key collision into a different submission's result.
    if v_submission.language is distinct from p_language
       or v_submission.code is distinct from p_code then
      raise exception 'idempotency_conflict' using errcode = 'P0001';
    end if;

    select pr.*
    into v_progress
    from public.problem_topic_progress pr
    where pr.student_id = p_student_id
      and pr.topic = v_topic;

    return jsonb_build_object(
      'created', false,
      'submission', to_jsonb(v_submission),
      'session', to_jsonb(v_session),
      'progress', to_jsonb(v_progress)
    );
  end if;

  if v_session.status <> 'active' then
    raise exception 'session_completed' using errcode = 'P0001';
  end if;

  insert into public.problem_submissions (
    question_id,
    session_id,
    student_id,
    client_submission_id,
    language,
    code,
    verdict,
    passed_tests,
    total_tests,
    runtime_ms,
    test_summary,
    result_details,
    all_passed,
    adaptive_difficulty,
    adaptive_focus,
    adaptive_reason
  ) values (
    v_question.id,
    v_question.session_id,
    p_student_id,
    p_client_submission_id,
    p_language,
    p_code,
    p_verdict,
    p_passed_tests,
    p_total_tests,
    null,
    coalesce(p_test_summary, '[]'::jsonb),
    coalesce(p_result_details, '[]'::jsonb),
    coalesce(p_all_passed, false),
    p_next_difficulty,
    p_next_focus,
    coalesce(p_next_reason, '')
  )
  on conflict (student_id, question_id, client_submission_id) do nothing
  returning * into v_submission;

  if v_submission.id is null then
    -- Defensive fallback for a concurrent insert that did not take the session
    -- lock (for example, a manual service-role write).
    select sub.*
    into v_submission
    from public.problem_submissions sub
    where sub.student_id = p_student_id
      and sub.question_id = p_question_id
      and sub.client_submission_id = p_client_submission_id;

    if v_submission.id is not null
       and (
         v_submission.language is distinct from p_language
         or v_submission.code is distinct from p_code
       ) then
      raise exception 'idempotency_conflict' using errcode = 'P0001';
    end if;

    select pr.*
    into v_progress
    from public.problem_topic_progress pr
    where pr.student_id = p_student_id
      and pr.topic = v_topic;

    return jsonb_build_object(
      'created', false,
      'submission', to_jsonb(v_submission),
      'session', to_jsonb(v_session),
      'progress', to_jsonb(v_progress)
    );
  end if;

  v_created := true;

  select
    count(*)::integer,
    count(*) filter (where sub.verdict = 'accepted')::integer
  into v_attempts_before, v_accepted_before
  from public.problem_submissions sub
  where sub.student_id = p_student_id
    and sub.question_id = p_question_id
    and sub.id <> v_submission.id;

  insert into public.problem_topic_progress as progress (
    student_id,
    topic,
    attempts,
    accepted,
    partial,
    wrong,
    hints_used,
    consecutive_failures,
    current_difficulty,
    last_outcome
  ) values (
    p_student_id,
    v_topic,
    1,
    case when p_outcome = 'accepted' then 1 else 0 end,
    case when p_outcome = 'partial' then 1 else 0 end,
    case when p_outcome not in ('accepted', 'partial') then 1 else 0 end,
    v_hints_used,
    case when p_outcome = 'accepted' then 0 else 1 end,
    p_next_difficulty,
    p_outcome
  )
  on conflict (student_id, topic) do update set
    attempts = progress.attempts + 1,
    accepted = progress.accepted
      + case when p_outcome = 'accepted' then 1 else 0 end,
    partial = progress.partial
      + case when p_outcome = 'partial' then 1 else 0 end,
    wrong = progress.wrong
      + case when p_outcome not in ('accepted', 'partial') then 1 else 0 end,
    hints_used = progress.hints_used + v_hints_used,
    consecutive_failures = case
      when p_outcome = 'accepted' then 0
      else progress.consecutive_failures + 1
    end,
    current_difficulty = p_next_difficulty,
    last_outcome = p_outcome,
    updated_at = now()
  returning * into v_progress;

  update public.problem_sessions
  set
    answered_count = answered_count
      + case when v_attempts_before = 0 then 1 else 0 end,
    accepted_count = accepted_count
      + case
          when p_outcome = 'accepted' and v_accepted_before = 0 then 1
          else 0
        end,
    current_difficulty = p_next_difficulty,
    current_topic = coalesce(p_next_topic, v_topic),
    updated_at = now()
  where id = v_session.id
    and student_id = p_student_id
  returning * into v_session_after;

  return jsonb_build_object(
    'created', v_created,
    'submission', to_jsonb(v_submission),
    'session', to_jsonb(v_session_after),
    'progress', to_jsonb(v_progress)
  );
end;
$function$;

revoke all on function public.record_problem_submission(
  uuid, uuid, uuid, text, text, text, integer, integer, jsonb, jsonb,
  boolean, integer, text, text, text, text, text
) from public, anon, authenticated;

grant execute on function public.record_problem_submission(
  uuid, uuid, uuid, text, text, text, integer, integer, jsonb, jsonb,
  boolean, integer, text, text, text, text, text
) to service_role;

comment on function public.record_problem_submission(
  uuid, uuid, uuid, text, text, text, integer, integer, jsonb, jsonb,
  boolean, integer, text, text, text, text, text
) is
  'Service-role-only atomic Problem Solving submission recorder. Idempotent on (student_id, question_id, client_submission_id).';
